// use the json generated by tests/nix/mine-cache-policy.nix not manually defined headers
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdir, readFile, writeFile, utimes } from 'node:fs/promises';
import { chromium } from '@playwright/test';
import { localRun, freshPort } from '../scripts/test-local.mjs';

test('merged mine asset policy revalidates stable CSS, JS and module imports on ordinary navigation', async t => {
  if (!process.env.MINE_CACHE_POLICY_FILE || !process.env.NGINX_BIN)
    return t.skip('requires scoped Nix policy JSON and a local nginx executable');
  const policy = JSON.parse(await readFile(process.env.MINE_CACHE_POLICY_FILE, 'utf8'));
  assert.equal(policy.status, 'PASS (scoped module evaluation only)');
  await localRun('asset-cache', async ({ directory, env, start, command, wait, ownBrowser }) => {
    const root = `${directory}/secrets/site`;
    for (const path of ['css', 'js']) await mkdir(`${root}/${path}`, { recursive: true });
    await writeFile(`${root}/index.html`, '<!doctype html><link rel="stylesheet" href="/css/theme.css"><script type="module" src="/js/account.js"></script><p>Stable assets</p>');
    async function release(version) {
      const files = {
        'css/theme.css': `body { color: ${version === 1 ? 'rgb(1, 2, 3)' : 'rgb(4, 5, 6)'}; }`,
        'js/account.js': `import { version } from './api.js'; window.assetVersion = ${version} + ':' + version;`,
        'js/api.js': `export const version = ${version};`,
      };
      for (const [file, text] of Object.entries(files)) {
        await writeFile(`${root}/${file}`, text);
        // Nginx ETags include mtime/size; avoid a same-second fixture collision.
        await utimes(`${root}/${file}`, 1700000000 + version, 1700000000 + version);
      }
    }
    await release(1);
    const port = await freshPort();
    const prefix = `${directory}/secrets/nginx`;
    await mkdir(prefix);
    const configuration = `${prefix}/nginx.conf`;
    await writeFile(configuration, `
      pid ${prefix}/nginx.pid;
      error_log ${prefix}/error.log;
      events {}
      http {
        access_log ${prefix}/access.log;
        types { text/html html; text/css css; application/javascript js; }
        server {
          listen 127.0.0.1:${port};
          root ${root};
          location ${policy.assetLocation} {
            try_files ${policy.tryFiles};
            ${policy.extraConfig}
          }
          location / { add_header Cache-Control "no-cache"; }
        }
      }
    `);
    const args = ['-p', prefix, '-e', `${prefix}/error.log`, '-c', configuration];
    await command(process.env.NGINX_BIN, [...args, '-t']);
    const nginx = await start(process.env.NGINX_BIN, [...args, '-g', 'daemon off;'], {}, 'nginx.log');
    const origin = `http://127.0.0.1:${port}`;
    await wait(async () => (await fetch(`${origin}/index.html`)).status === 200, nginx);
    const browser = await chromium.launch({ executablePath: await ownBrowser(process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || chromium.executablePath()), env });
    try {
      const page = await browser.newPage();
      const assets = [];
      page.on('response', response => {
        if (/\.(css|js)$/.test(new URL(response.url()).pathname)) assets.push(response);
      });
      await page.goto(`${origin}/index.html?document=1`);
      await page.waitForFunction(() => window.assetVersion === '1:1');
      assert.equal(await page.locator('body').evaluate(node => getComputedStyle(node).color), 'rgb(1, 2, 3)');
      await release(2);
      // Only the HTML navigation changes: no hard reload, cache bypass, new
      // browser context, or asset query/version suffix is involved.
      await page.goto(`${origin}/index.html?document=2`);
      assert.equal(await page.evaluate(() => window.assetVersion), '2:2');
      assert.equal(await page.locator('body').evaluate(node => getComputedStyle(node).color), 'rgb(4, 5, 6)');
      assert.equal(assets.length, 6);
      for (const response of assets) assert.equal(response.headers()['cache-control'], 'no-cache');
      const log = await readFile(`${prefix}/access.log`, 'utf8');
      for (const path of ['/css/theme.css', '/js/account.js', '/js/api.js'])
        assert.equal(log.split('\n').filter(line => line.includes(`GET ${path} HTTP/`) && line.includes(' 200 ')).length, 2, path);
    } finally { await browser.close(); }
  });
});
